-- Add gender and bio_extended columns to celebrities table.
-- gender: 'm' / 'f' / NULL (unknown or non-binary)
-- bio_extended: new expanded bio generated by the template engine (written before going live)

ALTER TABLE celebrities ADD COLUMN IF NOT EXISTS gender TEXT CHECK (gender IN ('m', 'f'));
ALTER TABLE celebrities ADD COLUMN IF NOT EXISTS bio_extended TEXT;

-- Backfill gender from bio text.
-- Conservative: only assign when the bio uses one gendered pronoun set exclusively.
-- 'her' is included in the female check but excluded from male to avoid "his or her" false positives.

UPDATE celebrities SET gender = 'f'
WHERE gender IS NULL
  AND bio IS NOT NULL
  AND bio ~* '\m(she|herself)\M'
  AND NOT bio ~* '\m(he|him|himself)\M';

UPDATE celebrities SET gender = 'm'
WHERE gender IS NULL
  AND bio IS NOT NULL
  AND bio ~* '\m(he|him|himself)\M'
  AND NOT bio ~* '\m(she|herself)\M';
